"use client";

import "../../styles/teum-base.css";
import "../../styles/components/saved-view-menu.css";
import type { HTMLAttributes } from "react";
import { cn } from "../../lib/cn";
import { SavedViews, type SavedViewsProps } from "./data-toolbar";

export type SavedViewMenuProps = SavedViewsProps & {
  className?: string;
};

export function SavedViewMenu({ className, ...props }: SavedViewMenuProps) {
  return (
    <span className={cn("teum-saved-view-menu", className)}>
      <SavedViews {...props} />
    </span>
  );
}

export type SavedViewMenuContainerProps = HTMLAttributes<HTMLSpanElement>;

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-saved-view-menu {
  display: inline-flex;
  min-width: 0;
  vertical-align: middle;
}
}
